		config := ""
		if u.Config != nil {
			configBytes, err := u.Config.ToDB()
			config = string(configBytes)
			if err != nil {
				config = err.Error()
			}
		}
		format.WriteString("\n\tunits[%d]: ID=%d RepoID=%d Type=%s Config=%s")
